style.css:
* {
    font-family: Georgia, serif !important; /* Georgia font */
}

/* Global Background and Text Colors */
* {
    background-color: #ffe4e1 !important; /* Light pink background */
    color: #4b2c2c !important; /* Dark text for readability */
    border-color: #ffc0cb !important; /* Light pink borders */
}

/* Links */
a, a:visited {
    color: #ff8cb5 !important; /* Pink links */
}

/* Button and Form Input Styling */
button, input, textarea, select, [role="button"], [type="button"], [type="submit"], [type="reset"] {
    background-color: #ffc0cb !important; /* Light pink background */
    color: #4b2c2c !important; /* Dark text */
    border: 1px solid #d2698e !important; /* Pink borders */
    box-shadow: none !important; /* Remove any shadows */
    outline: none !important; /* Remove outlines */
    text-shadow: none !important; /* Remove text shadows */
    padding: 10px 15px !important; /* Consistent padding */
    font-size: 14px !important; /* Consistent font size */
    text-align: center !important; /* Center-align text */
    border-radius: 5px !important; /* Smooth corners */
    display: inline-block !important;
    appearance: none !important; /* Remove browser-specific styles */
    margin: 5px !important; /* Small margin to prevent crowding */
}

/* Fix for Internal Button Text or Child Elements */
button *, [role="button"] * {
    background: none !important; /* Remove nested backgrounds */
    background-color: transparent !important; /* Ensure no overlays */
    color: inherit !important; /* Inherit parent text color */
}

/* Hover and Active States */
button:hover, input:hover, textarea:hover, select:hover, [role="button"]:hover {
    background-color: #ffb6c1 !important; /* Slightly darker pink */
    color: #4b2c2c !important;
}

button:active, input:active, [role="button"]:active {
    background-color: #ffa6b0 !important; /* Even darker pink for active state */
}

/* Disabled Elements */
button:disabled, input:disabled, textarea:disabled, select:disabled {
    background-color: #ffe4e1 !important; /* Light pink for disabled */
    color: #a29a9a !important; /* Muted text color */
    opacity: 0.6 !important; /* Dim disabled elements */
}

/* Placeholder Text */
::placeholder {
    color: #d2698e !important; /* Pink placeholder text */
}

/* Selection Highlight */
*::selection {
    background-color: #ffc0cb !important; /* Pink selection background */
    color: #4b2c2c !important; /* Dark text */
}

/* Additional Specific Fixes for Edge Cases */
button span, input[type="submit"], input[type="button"] {
    background-color: #ffc0cb !important; /* Force background consistency */
    box-shadow: none !important;
    border: none !important;
}
